import { getTranslations } from "next-intl/server";

import { SmokeCard } from "@/components/smoke/smoke-card";

export default async function RegistrySmokePage() {
  const t = await getTranslations("smoke");

  return (
    <main className="flex min-h-screen flex-col items-center justify-center gap-6 p-8">
      <h1 className="text-3xl font-bold">{t("heading")}</h1>
      <SmokeCard />
    </main>
  );
}

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

export function SmokeCard() {
  return (
    <Card>
      <CardHeader>
        <CardTitle>Registry smoke test</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        <p className="text-sm text-muted-foreground">
          If you can see this card, the Intelligo registry pipeline built,
          installed, and rendered correctly.
        </p>
        <Button>It works</Button>
      </CardContent>
    </Card>
  );
}
